// DragonBreak Online: the nobility (Nate, 10 Oct 2026; docs/nobility/DESIGN.md). Loaded by gamemode.js after court.js.
//
// A hold is divided into fiefs, real towns only (nobility-fiefs.json, generated by tools/nobility_fiefs.py from the towns'
// LCTN records). Its ruler, the Count or Countess of a Cyrodiil county or the Jarl of a Skyrim hold (the hold faction's
// leader, or the account seated in the court's first office), grants, changes and revokes titles there, and nobody else
// (a Lead GM may only revoke, in an emergency, announced as the staff's act):
//   Cyrodiil  Baron / Baroness   holds a fief (a town)
//             Lord / Lady        an estate, no town
//             Knight / Dame      an honour, no land
//   Skyrim    Lord / Lady        holds a fief (a holding)
//             Thane              an honour
// A fief may style its holder otherwise, with the same powers (config fiefTitles): Underarch Harbor, Solitude's eastern
// harbor, is held by a Harbormaster (Nate, 16 Oct).
// Titles belong to one character (its actor id, as property does once property-per-character ships), one title per character
// per hold and one holder per fief. Every grant, change and revocation is audited and announced in the words of a decree.
// A fief's holder has powers only inside it, enforced by the fork's housingSystem.ts through __dboNobility below: they manage
// its buildings as a steward does (grant, take back, assign rooms and chests) and their own buildings there do not count
// against the one-building cap. They also assess and rent out property there (economy.js, tenancy.js, by
// __dboHousing.isFiefHolder). They are no court member: no tax rate, arrests or posts.
// Tax (economy.js, through __dboNobilityFiefCut): fiefShare of the weekly property tax on a building in a fief goes to that
// fief's treasury (bank.js __dboFiefTreasury: deposits only, nobody withdraws), the rest to the hold as before.
//
// Journal contract (journal.js): __dboJournalSections.nobility = { visible, view, label } puts the section at payload.nobility,
// for a front whose caps list 'journalTab:nobility'. Events carry the journal nonce first and answer through
// __dboJournalLimited:
//   nobilityGrant  [nonce, holdId, nameOrTag, titleId, fiefId | estateName]   the ruler only
//   nobilityRevoke [nonce, holdId, actorHex]                                  the ruler, or a Lead GM in an emergency
// enabled (config nobility.enabled, default false): off, there is no tab, no power in the fork and no tax share.
// State in nobility.json (runtime, gitignored).
'use strict';
const fs = require('fs');
const path = require('path');

module.exports = (api) => {
  const { mp, log, audit, who, display, nameOf, tagOf, onUi, onlineActors, profileOf, cfg, zoneById, readOfficials, ranksOf,
    accountActors, officialTarget, every } = api;
  const personal = typeof api.personal === 'function' ? api.personal : () => {};
  // Lead GM and above: an emergency revoke only, never a grant (Nate, 10 Oct)
  const isLeadStaff = typeof api.isLeadStaff === 'function' ? api.isLeadStaff : () => false;
  const announce = typeof api.announce === 'function' ? api.announce : () => {};
  // The roll and the ruler name people by their own name, never a beast's, and a mask's only while rosterPrivacy.masks
  // is off (gamemode.js ownNameOf; tracker 1559074270959640676: a ruler in a beast form was listed as the beast)
  const ownNameOf = typeof api.ownNameOf === 'function' ? api.ownNameOf : nameOf;
  // The answer to a grant names its character as the ruler asked for them (gamemode.js publicNameOf): a mask granted a
  // title by the #TAG drawn under it stays the mask there; the roll and the decree follow rosterPrivacy.masks
  const publicNameOf = typeof api.publicNameOf === 'function' ? api.publicNameOf : nameOf;
  const C = Object.assign({
    enabled: false, fiefShare: 0.25, maxEstateName: 40,
    // zone id -> 'cyrodiil' | 'skyrim': which titles its ruler grants; a zone not listed is a Skyrim hold
    realms: { bruma: 'cyrodiil' },
    // One-time grants made when the switch is on (the migration: Lord Elion, Baron of Mountain Watch): { fief | hold, title,
    // profile, name }; each is applied once, to the account's character carrying that name, and only to a vacant fief
    seed: [],
    // fief id -> { m, f }: the style of that fief's holder in place of the realm's fief title (Lord, Baron), with the same
    // powers. Underarch Harbor, Solitude's eastern harbor, is held by a Harbormaster (Nate, 16 Oct; #suggestions
    // 1560585290286891069)
    fiefTitles: { 'underarch-harbor': { m: 'Harbormaster', f: 'Harbormaster' } },
  }, (cfg && cfg.nobility) || {});
  const FILE = path.resolve('nobility.json');
  const FIEFS_FILE = path.resolve('nobility-fiefs.json');
  const CELL = 4096;

  // ---- titles ----------------------------------------------------------------------------------------------------------
  const TITLES = {
    cyrodiil: [
      { id: 'baron', m: 'Baron', f: 'Baroness', fief: true },
      { id: 'lord', m: 'Lord', f: 'Lady', estate: true },
      { id: 'knight', m: 'Knight', f: 'Dame' },
    ],
    skyrim: [
      { id: 'lord', m: 'Lord', f: 'Lady', fief: true },
      { id: 'thane', m: 'Thane', f: 'Thane' },
    ],
  };
  const RULER = { cyrodiil: { m: 'Count', f: 'Countess' }, skyrim: { m: 'Jarl', f: 'Jarl' } };
  const realmOf = (zid) => (C.realms && C.realms[zid] === 'cyrodiil' ? 'cyrodiil' : 'skyrim');
  const titleDef = (zid, id) => TITLES[realmOf(zid)].find((t) => t.id === String(id || '').toLowerCase()) || null;
  // A fief whose holder has a style of their own (config fiefTitles): the word for this holder, '' for the realm's title
  const fiefWord = (fid, female) => {
    const t = C.fiefTitles && typeof C.fiefTitles === 'object' ? C.fiefTitles[String(fid || '')] : null;
    if (!t || typeof t !== 'object') return '';
    const pick = (v) => (typeof v === 'string' ? v.trim() : '');
    return (female ? pick(t.f) || pick(t.m) : pick(t.m) || pick(t.f));
  };
  // "The Rift" reads "of the Rift" inside a sentence
  const ofPlace = (name) => String(name || '').replace(/^The /, 'the ');

  // ---- state -----------------------------------------------------------------------------------------------------------
  const S = globalThis.__dboNobilityState || (globalThis.__dboNobilityState = { data: null });
  // ref -> fief id ('' for none), rebuilt on every load: the fief table may have changed
  S.fiefCache = new Map();
  const fill = (d) => {
    if (!Array.isArray(d.nobles)) d.nobles = [];
    if (!d.seeded || typeof d.seeded !== 'object') d.seeded = {};
    return d;
  };
  const data = () => {
    if (S.data) return S.data;
    let d = null;
    try { d = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e) { d = null; }
    S.data = fill(d && typeof d === 'object' ? d : {});
    return S.data;
  };
  if (S.data) fill(S.data);
  const save = () => { const tmp = FILE + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(data(), null, 1)); fs.renameSync(tmp, FILE); };

  // ---- fiefs -----------------------------------------------------------------------------------------------------------
  const FIEFS = (() => { try { const v = JSON.parse(fs.readFileSync(FIEFS_FILE, 'utf8')); return Array.isArray(v.fiefs) ? v.fiefs : []; } catch (e) { log('nobility: nobility-fiefs.json unreadable', e.message); return []; } })();
  const fiefById = (id) => FIEFS.find((f) => f.id === String(id || '')) || null;
  const norm = (d) => String(d || '').toLowerCase();
  const byCell = new Map(), byGrid = new Map();
  for (const f of FIEFS) {
    for (const c of f.cells || []) byCell.set(norm(c), f);
    for (const g of f.grid || []) byGrid.set(`${norm(f.world)}|${g[0]}|${g[1]}`, f);
  }
  // The fief a reference stands in: its interior cell, else the worldspace cell under it. undefined when it cannot be read
  const fiefAtRef = (ref) => {
    const r = Number(ref) >>> 0; if (!r) return '';
    if (S.fiefCache.has(r)) return S.fiefCache.get(r);
    let w, p;
    try { w = norm(mp.get(r, 'worldOrCellDesc')); p = mp.get(r, 'pos'); } catch (e) { return undefined; }
    if (!w) return undefined;
    let f = byCell.get(w);
    if (!f && Array.isArray(p)) f = byGrid.get(`${w}|${Math.floor(Number(p[0]) / CELL)}|${Math.floor(Number(p[1]) / CELL)}`);
    const id = f ? f.id : '';
    S.fiefCache.set(r, id);
    return id;
  };
  const fiefOf = (refs) => {
    for (const r of [].concat(refs || [])) { const id = fiefAtRef(r); if (id) return id; }
    return '';
  };

  // ---- characters --------------------------------------------------------------------------------------------------------
  const exists = (a) => { if (!a) return false; try { mp.get(a >>> 0, 'type'); return true; } catch (e) { return false; } };
  const isFemale = (a, fallback) => { try { const app = mp.get(a >>> 0, 'appearance'); return app ? !!app.isFemale : !!fallback; } catch (e) { return !!fallback; } };
  const tagSafe = (a) => { try { return String(tagOf(a) || ''); } catch (e) { return ''; } };
  const isOnline = (a) => onlineActors().includes(a >>> 0);
  const hex = (a) => (Number(a) >>> 0).toString(16);
  // A title of a character that no longer exists (deleted at character select) lapses; the entry stays out of every view
  const living = () => data().nobles.filter((n) => exists(n.actor));
  const nobleOf = (actor, zid) => data().nobles.find((n) => (n.actor >>> 0) === (actor >>> 0) && n.hold === zid) || null;
  const holderEntry = (fid) => living().find((n) => n.fief === fid) || null;
  const labelOf = (n) => {
    const def = titleDef(n.hold, n.title); if (!def) return n.title;
    const female = exists(n.actor) ? isFemale(n.actor, n.female) : !!n.female;
    const word = female ? def.f : def.m;
    if (def.fief) { const f = fiefById(n.fief); return `${fiefWord(n.fief, female) || word} of ${f ? f.name : n.fief}`; }
    if (def.estate) return n.estate ? `${word} of ${n.estate}` : word;
    const z = zoneById(n.hold);
    return `${word} of ${ofPlace(z ? z.name : n.hold)}`;
  };

  // ---- the ruler ---------------------------------------------------------------------------------------------------------
  // The hold faction's leader (a character, guilds.js), or the account seated in the court's first office (officials.json)
  const rules = (a, zid) => {
    const z = zoneById(zid); if (!z) return false;
    try {
      const fid = typeof globalThis.__dboCourtFaction === 'function' ? globalThis.__dboCourtFaction(z.id) : null;
      const guilds = typeof globalThis.__dboGuildsOf === 'function' ? (globalThis.__dboGuildsOf(a) || []) : [];
      if (fid && guilds.some((g) => g.id === fid && g.role === 'leader')) return true;
    } catch (e) { /* no guilds */ }
    const top = (z.officials || [])[0];
    try { return !!top && (ranksOf(profileOf(a)) || []).some((m) => m.zone && m.zone.id === z.id && m.rank === top); } catch (e) { return false; }
  };
  // "the Countess of Bruma": the style of whoever rules, by the character acting, else the seated account's first character
  const rulerStyle = (zid, actor) => {
    const z = zoneById(zid); const r = RULER[realmOf(zid)];
    let a = actor >>> 0;
    if (!a) {
      const top = z && (z.officials || [])[0];
      const pid = top ? Number((((readOfficials() || {})[z.id] || {})[top] || [])[0]) : NaN;
      a = Number.isFinite(pid) ? (onlineActors().find((x) => profileOf(x) === pid) || accountActors(pid).find(exists) || 0) : 0;
    }
    const word = a && isFemale(a) ? r.f : r.m;
    return `the ${word} of ${ofPlace(z ? z.name : zid)}`;
  };
  const rulerView = (zid) => {
    const z = zoneById(zid); const top = z && (z.officials || [])[0];
    const pid = top ? Number((((readOfficials() || {})[z.id] || {})[top] || [])[0]) : NaN;
    if (!Number.isFinite(pid)) return null;
    const a = onlineActors().find((x) => profileOf(x) === pid) || accountActors(pid).find(exists) || 0;
    return { name: a ? String(ownNameOf(a)) : '', style: rulerStyle(zid, a).replace(/^the /, '') };
  };

  // ---- the decrees ---------------------------------------------------------------------------------------------------------
  const ESTATE_RX = /^[A-Za-z][A-Za-z' -]*$/;
  const estateName = (raw) => {
    const s = String(raw == null ? '' : raw).replace(/\s+/g, ' ').trim();
    if (s.length < 2 || s.length > C.maxEstateName || !ESTATE_RX.test(s)) return { error: `An estate's name is 2 to ${C.maxEstateName} letters, spaces, hyphens or apostrophes.` };
    const bad = typeof globalThis.__dboProseProblem === 'function' ? globalThis.__dboProseProblem(s) : null;
    if (bad) return { error: `The word "${bad}" will not do in an estate's name.` };
    return { name: s };
  };
  const decree = (zid, by, text) => {
    const line = `By decree of ${rulerStyle(zid, by)}, ${text}`;
    try { announce(line); } catch (e) { log('nobility: announce failed', e.message); }
    return line;
  };
  // Grants (or changes) a title; by is the ruler's actor, 0 for the migration. { error } or { text }
  const grant = (by, zid, tg, titleId, extra, how) => {
    const z = zoneById(zid); if (!z) return { error: 'There is no such hold.' };
    const def = titleDef(zid, titleId);
    if (!def) return { error: `${z.name} grants the titles ${TITLES[realmOf(zid)].map((t) => `${t.m}/${t.f}`.replace(/^(\w+)\/\1$/, '$1')).join(', ')}.` };
    const actor = tg.actor >>> 0;
    if (!exists(actor)) return { error: 'That character no longer exists.' };
    let fief = '', estate = '';
    if (def.fief) {
      const f = fiefById(extra);
      if (!f || f.hold !== z.id) return { error: `Choose one of the fiefs of ${z.name}.` };
      const holder = holderEntry(f.id);
      if (holder && (holder.actor >>> 0) !== actor) return { error: `${f.name} is held by ${holder.name}. Revoke that title first.` };
      fief = f.id;
    }
    if (def.estate) { const e = estateName(extra); if (e.error) return e; estate = e.name; }
    const before = nobleOf(actor, z.id);
    const was = before ? labelOf(before) : '';
    const entry = { actor, profile: Number(tg.pid) || profileOf(actor), name: String(ownNameOf(actor) || tg.label || ''), female: isFemale(actor), hold: z.id, title: def.id,
      fief: fief || undefined, estate: estate || undefined, at: Date.now(), by: by ? who(by) : String(how || 'migration') };
    const asked = String(publicNameOf(actor) || entry.name);
    if (before && labelOf(entry) === was) return { error: `${asked} is already ${was}.` };
    data().nobles = data().nobles.filter((n) => n !== before).concat([entry]);
    save();
    const label = labelOf(entry);
    const text = def.id === 'knight' ? `${entry.name} is made a ${label}` : `${entry.name} is named ${label}`;
    const line = decree(z.id, by, `${text}${was ? `, formerly ${was}` : ''}.`);
    audit(`NOBILITY ${by ? who(by) : String(how || 'migration')}: ${tg.who || entry.name} (character ${hex(actor)}) is ${label} (${z.name})${was ? `, was ${was}` : ''}${how ? ` [${how}]` : ''}`);
    if (isOnline(actor) && actor !== (by >>> 0)) personal(actor, line);
    return { text: `${asked} is now ${label}.` };
  };
  // staff: a Lead GM's emergency revoke, announced plainly rather than as the ruler's decree
  const revoke = (by, zid, actor, staff) => {
    const z = zoneById(zid); if (!z) return { error: 'There is no such hold.' };
    const n = nobleOf(actor, z.id); if (!n) return { error: 'That character holds no title here.' };
    const label = labelOf(n);
    data().nobles = data().nobles.filter((x) => x !== n);
    save();
    let line;
    if (staff) { line = `A title was revoked by the staff: ${n.name} is no longer ${label}.`; try { announce(line); } catch (e) { log('nobility: announce failed', e.message); } }
    else line = decree(z.id, by, `${n.name} is no longer ${label}.`);
    audit(`NOBILITY ${staff ? 'STAFF ' : ''}${who(by)}: revoked ${n.name} (character ${hex(n.actor)}) as ${label} (${z.name})`);
    if (isOnline(n.actor) && (n.actor >>> 0) !== (by >>> 0)) personal(n.actor, line);
    return { text: `${n.name} is no longer ${label}.` };
  };

  // ---- the fork's housing and the economy ask these ------------------------------------------------------------------------
  globalThis.__dboNobility = {
    enabled: () => !!C.enabled,
    fiefOf: (refs) => (C.enabled ? fiefOf(refs) : ''),
    holderOf: (fid) => {
      if (!C.enabled) return null;
      const n = holderEntry(String(fid || '')); return n ? { actor: n.actor >>> 0, profile: Number(n.profile) || 0, name: n.name } : null;
    },
    // Whether this character holds the fief one of these references stands in
    holdsFiefAt: (actor, refs) => {
      if (!C.enabled) return false;
      const id = fiefOf(refs); if (!id) return false;
      const n = holderEntry(id); return !!n && (n.actor >>> 0) === (Number(actor) >>> 0);
    },
  };
  // economy.js: the fief's share of a building's weekly tax, { id, name, share } or null
  globalThis.__dboNobilityFiefCut = (ref, rec, tax) => {
    if (!C.enabled) return null;
    const rate = Math.min(0.5, Math.max(0, Number(C.fiefShare) || 0));
    const share = Math.floor((Number(tax) || 0) * rate); if (share <= 0) return null;
    const id = fiefOf([ref, rec && Number(rec.partner) >>> 0].filter(Boolean)); if (!id) return null;
    const f = fiefById(id); return f ? { id, name: f.name, share } : null;
  };

  // ---- the Nobility tab --------------------------------------------------------------------------------------------------
  const treasury = (fid) => { try { return globalThis.__dboFiefTreasury ? Math.floor(Number(globalThis.__dboFiefTreasury.balance(fid)) || 0) : null; } catch (e) { return null; } };
  const claimedRefs = () => { try { const v = JSON.parse(fs.readFileSync(path.resolve('housing.json'), 'utf8')); return Array.isArray(v) ? v.map((x) => Number(x) >>> 0) : []; } catch (e) { return []; } };
  // The buildings claimed in a fief: one row per building (a place's root, or a way in that is no member)
  const propertiesIn = (fid) => {
    const H = globalThis.__dboHousing; if (!H || typeof H.recordOf !== 'function') return [];
    const out = [];
    for (const ref of claimedRefs()) {
      try {
        if (typeof H.primaryOf === 'function' && (Number(H.primaryOf(ref)) >>> 0) !== ref) continue;
        const rec = H.recordOf(ref); if (!rec || !rec.owner) continue;
        if (typeof H.isBuilding === 'function' && !H.isBuilding(ref)) continue;
        if (fiefOf([ref, Number(rec.partner) >>> 0].filter(Boolean)) !== fid) continue;
        const door = typeof H.doorName === 'function' ? String(H.doorName(ref) || '') : '';
        out.push({ ref: hex(ref), name: String(rec.name || door || 'A building'), owner: String(rec.ownerName || '') });
      } catch (e) { /* a claim that cannot be read is left out */ }
    }
    return out.sort((x, y) => x.name.localeCompare(y.name));
  };
  const nobleView = (n) => ({ actor: hex(n.actor), name: isOnline(n.actor) ? String(ownNameOf(n.actor)) : n.name, tag: tagSafe(n.actor), online: isOnline(n.actor),
    title: n.title, label: labelOf(n), fief: n.fief || '', estate: n.estate || '', since: n.at });
  const holdIds = (a) => {
    const ids = new Set(Object.keys(C.realms || {}));
    for (const f of FIEFS) ids.add(f.hold);
    for (const n of living()) ids.add(n.hold);
    return [...ids].filter((id) => zoneById(id)).filter((id) => FIEFS.some((f) => f.hold === id) || living().some((n) => n.hold === id) || rules(a, id));
  };
  const holdView = (a, zid) => {
    const z = zoneById(zid); const ruler = rules(a, zid);
    const nobles = living().filter((n) => n.hold === zid).sort((x, y) => x.at - y.at);
    const fiefs = FIEFS.filter((f) => f.hold === zid).map((f) => {
      const h = holderEntry(f.id);
      const mine = !!h && (h.actor >>> 0) === (a >>> 0);
      return { id: f.id, name: f.name, buildings: (f.buildings || []).length, holder: h ? nobleView(h) : null, treasury: ruler || mine ? treasury(f.id) : null };
    });
    const titles = ruler ? TITLES[realmOf(zid)].map((t) => ({ id: t.id, label: t.m === t.f ? t.m : `${t.m} / ${t.f}`, needs: t.fief ? 'fief' : t.estate ? 'estate' : '' })) : [];
    return { id: z.id, name: z.name, realm: realmOf(zid), ruler: rulerView(zid), isRuler: ruler, canRevoke: ruler || isLeadStaff(a), fiefs, roll: nobles.map(nobleView), titles };
  };
  const mineView = (a) => living().filter((n) => (n.actor >>> 0) === (a >>> 0)).map((n) => {
    const f = n.fief ? fiefById(n.fief) : null;
    return { hold: n.hold, label: labelOf(n), since: n.at, fief: f ? { id: f.id, name: f.name, treasury: treasury(f.id), properties: propertiesIn(f.id) } : null };
  });
  const view = (a) => {
    const holds = holdIds(a).map((id) => holdView(a, id));
    const mine = mineView(a);
    const sel = S.lastHold instanceof Map ? S.lastHold.get(a >>> 0) : '';
    return { enabled: !!C.enabled, fiefShare: Math.round(Math.min(0.5, Math.max(0, Number(C.fiefShare) || 0)) * 100), holds, mine,
      selected: (holds.find((h) => h.id === sel) || holds.find((h) => h.isRuler) || holds.find((h) => mine.some((m) => m.hold === h.id)) || holds[0] || {}).id || '' };
  };
  if (!(S.lastHold instanceof Map)) S.lastHold = new Map();
  const sections = globalThis.__dboJournalSections || (globalThis.__dboJournalSections = {});
  if (C.enabled) sections.nobility = { visible: () => true, view, label: () => 'Nobility' };
  else delete sections.nobility;

  const fresh = (a, args) => typeof globalThis.__dboJournalFresh === 'function' && !!globalThis.__dboJournalFresh(a, String((args || [])[0] || ''));
  const answer = (a, fn) => {
    const run = () => { let r; try { r = fn(); } catch (e) { log('nobility: action failed', e.stack || e.message); r = { error: 'That cannot be done just now.' }; } return { tab: 'nobility', text: r.error || r.text || '', kind: r.error ? 'refused' : 'ok' }; };
    if (typeof globalThis.__dboJournalLimited === 'function') globalThis.__dboJournalLimited(a, run);
  };
  const holdFor = (a, id) => {
    const z = zoneById(String(id || '')); if (!z) return null;
    S.lastHold.set(a >>> 0, z.id);
    return z;
  };
  const notRuler = (z) => { const r = RULER[realmOf(z.id)]; return { error: `Only the ${r.m === r.f ? r.m : `${r.m} or ${r.f}`} of ${ofPlace(z.name)} grants and revokes titles there.` }; };
  onUi('nobilityGrant', (a, args) => {
    if (!C.enabled || !fresh(a, args)) return;
    answer(a, () => {
      const z = holdFor(a, args[1]); if (!z) return { error: 'There is no such hold.' };
      if (!rules(a, z.id)) return notRuler(z);
      const q = String(args[2] || '').trim();
      if (!q || /^\d+$/.test(q)) return { error: 'Name the character, or give their #TAG.' };
      const tg = officialTarget(q); if (tg.error) return tg;
      if (tg.pid === profileOf(a)) return { error: 'No ruler raises their own house: a title goes to someone else\'s character.' };
      return grant(a, z.id, tg, args[3], args[4]);
    });
  });
  onUi('nobilityRevoke', (a, args) => {
    if (!C.enabled || !fresh(a, args)) return;
    answer(a, () => {
      const z = holdFor(a, args[1]); if (!z) return { error: 'There is no such hold.' };
      const ruler = rules(a, z.id);
      if (!ruler && !isLeadStaff(a)) return notRuler(z);
      const actor = parseInt(String(args[2] || ''), 16) >>> 0;
      return actor ? revoke(a, z.id, actor, !ruler) : { error: 'That character holds no title here.' };
    });
  });

  // ---- the migration (config nobility.seed) -------------------------------------------------------------------------------
  const nameKey = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9' -]/g, '').replace(/\s+/g, ' ').trim();
  const seedKey = (s) => `${s.fief || s.hold}|${s.title}|${s.profile}|${nameKey(s.name)}`;
  const applySeeds = () => {
    const d = data();
    for (const s of Array.isArray(C.seed) ? C.seed : []) {
      const key = seedKey(s);
      if (!s || d.seeded[key]) continue;
      const f = s.fief ? fiefById(s.fief) : null;
      const zid = f ? f.hold : String(s.hold || '');
      const want = nameKey(s.name);
      const cands = accountActors(Number(s.profile)).filter(exists).filter((x) => { const n = nameKey(nameOf(x)); return !!want && (n === want || ` ${n} `.includes(` ${want} `)); });
      if (cands.length !== 1) { if (!S.seedWarned) log(`nobility: seed ${key} waits: ${cands.length} characters of profile ${s.profile} carry "${s.name}"`); continue; }
      const actor = cands[0];
      const r = grant(0, zid, { actor, pid: Number(s.profile), label: nameOf(actor), who: who(actor) }, s.title, f ? f.id : s.estate, 'migration');
      d.seeded[key] = { at: Date.now(), actor: hex(actor), result: r.error || r.text };
      save();
      log(`nobility: seed ${key}: ${r.error || r.text}`);
    }
    S.seedWarned = true;
  };
  if (typeof every === 'function') every('nobilitySeed', 60000, () => { if (C.enabled) { try { applySeeds(); } catch (e) { log('nobility: seeds failed', e.message); } } });

  // ---- chat, for a client without the tab ------------------------------------------------------------------------------------
  if (typeof api.registerChatCommand === 'function') {
    api.registerChatCommand('nobility', (a) => {
      if (!C.enabled) return personal(a, 'There is no nobility to speak of yet.');
      try { if (typeof globalThis.__dboJournalOpenTab === 'function' && globalThis.__dboJournalOpenTab(a >>> 0, 'nobility') === true) return; } catch (e) { /* chat instead */ }
      const lines = holdIds(a).map((id) => { const h = holdView(a, id); return `${h.name}: ${h.roll.length ? h.roll.map((n) => `${n.name}, ${n.label}`).join('; ') : 'no titles granted'}`; });
      personal(a, lines.length ? lines.join(' | ') : 'No hold keeps a roll of nobles yet.');
    }, { help: 'the nobility roll of the holds (F3 Nobility shows it, and the ruler grants titles there)' });
  }

  log(`nobility ${C.enabled ? 'on' : 'off'}: ${FIEFS.length} fiefs, ${living().length} titles, fief share ${Math.round((Number(C.fiefShare) || 0) * 100)}%`);
  return { grant, revoke, fiefOf, view, rules, applySeeds, labelOf };
};
